import{_ as i,c as a,o as t,a2 as e}from"./chunks/framework.PGES7OoM.js";const u=JSON.parse('{"title":"getQuote","description":"Estimate a review screen without exposing note inputs, bearer outputs, or mutable plans.","frontmatter":{"editLink":false,"rawMarkdown":"# getQuote\\n\\nEstimate a review screen without exposing note inputs, bearer outputs, or mutable plans.\\n\\n## Import\\n\\n```ts\\nimport { getQuote } from \\"@0xcurvy/curvy-sdk/actions\\";\\n```\\n\\n## Usage\\n\\n```ts\\nconst result = await getQuote({ intent, config });\\n```\\n\\n## Signature\\n\\n```ts\\nfunction getQuote(parameters: EstimateIntentParameters): Promise<Quote>\\n```\\n\\n## Returns\\n\\n`Promise<Quote>`\\n\\nThe action resolves or returns the value shown in the signature.\\n\\n## Parameters\\n\\n### `intent`\\n\\n- **Type:** `Intent`\\n- **Required:** yes\\n\\nThe transfer intent to estimate for the review screen.\\n\\n```ts\\nconst result = await getQuote({\\n  intent, // [!code focus]\\n});\\n```\\n\\n### `accountId`\\n\\n- **Type:** `string`\\n- **Required:** no\\n\\nExplicit account guard. This config has one bearer session, so it must be the active account.\\n\\n```ts\\nconst result = await getQuote({\\n  intent,\\n  accountId, // [!code focus]\\n});\\n```\\n\\n### `signal`\\n\\n- **Type:** `AbortSignal`\\n- **Required:** no\\n\\nCancel a superseded estimate; cancelled results are never published.\\n\\n```ts\\nconst result = await getQuote({\\n  intent,\\n  signal, // [!code focus]\\n});\\n```\\n\\n### `minimumInputFinalityPolicy`\\n\\n- **Type:** `InputFinalityPolicy`\\n- **Required:** no\\n\\nIntegration-level lower bound that account/intent settings cannot weaken.\\n\\n```ts\\nconst result = await getQuote({\\n  intent,\\n  minimumInputFinalityPolicy, // [!code focus]\\n});\\n```\\n\\n### `submissionMode`\\n\\n- **Type:** `SubmissionMode`\\n- **Required:** no\\n\\nOverride the config\'s submission path for this estimate and its prepared execution.\\n\\n```ts\\nconst result = await getQuote({\\n  intent,\\n  submissionMode, // [!code focus]\\n});\\n```\\n\\n### `config`\\n\\n- **Type:** `CurvyConfig`\\n- **Required:** no\\n\\nCurvy config to use. Defaults to the ambient config.\\n\\n```ts\\nconst result = await getQuote({\\n  intent,\\n  config, // [!code focus]\\n});\\n```\\n\\n## Errors\\n\\nErrors from config resolution and the underlying SDK operation are propagated to the caller.\\n\\n## Related\\n\\n- [Interacting with assets guide](/for-programmers/interacting-with-assets)\\n\\n## Source\\n\\n[packages/@0xcurvy/sdk/src/actions/views/getQuote.ts](https://github.com/0xCurvy/curvy-monorepo/blob/main/packages/@0xcurvy/sdk/src/actions/views/getQuote.ts)\\n","rawMarkdownPath":"/_raw/sdk/actions/views/getQuote.md","rawMarkdownTitle":"getQuote","rawMarkdownUrl":"https://docs.curvy.box/_raw/sdk/actions/views/getQuote.md"},"headers":[],"params":{"sdkReferenceKind":"action","category":"views","action":"getQuote"},"relativePath":"sdk/actions/views/getQuote.md","filePath":"sdk/actions/[category]/[action].md","lastUpdated":1786448401000}'),n={name:"sdk/actions/views/getQuote.md"};function l(o,s,r,h,p,d){return t(),a("div",null,[...s[0]||(s[0]=[e("",42)])])}const k=i(n,[["render",l]]);export{u as __pageData,k as default};
